module RoundingUnit(
  input  [9:0] io_in,
  input        io_roundIn,
               io_stickyIn,
               io_signIn,
  input  [2:0] io_rm,
  output [9:0] io_out,
  output       io_inexact,
               io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 10'h1 : io_in;
  assign io_inexact = inexact;
  assign io_cout = r_up & (&io_in);
endmodule

module TininessRounder(
  input         io_in_sign,
  input  [13:0] io_in_sig,
  input  [2:0]  io_rm,
  output        io_tininess
);

  wire _rounder_io_cout;
  RoundingUnit rounder (
    .io_in       (io_in_sig[11:2]),
    .io_roundIn  (io_in_sig[1]),
    .io_stickyIn (io_in_sig[0]),
    .io_signIn   (io_in_sign),
    .io_rm       (io_rm),
    .io_out      (/* unused */),
    .io_inexact  (/* unused */),
    .io_cout     (_rounder_io_cout)
  );
  assign io_tininess =
    io_in_sig[13:12] == 2'h0 | io_in_sig[13:12] == 2'h1 & ~_rounder_io_cout;
endmodule

